package net.civeira.phylax.features.access.userconsentedscopes.domain.valueobject;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.userconsentedscopes.domain.UserConsentedScopes;

@RequiredArgsConstructor
public class ScopeValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ScopeVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getScope() {
    return value.flatMap(ScopeVO::getScope);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ScopeVO> getScopeValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ScopeVO readScope(final Optional<UserConsentedScopes> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(UserConsentedScopes::getScopeValue).orElseGet(ScopeVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param scope
   * @return
   */
  public T scope(ScopeVO scope) {
    this.value = Optional.of(scope);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param scope
   * @return
   */
  public T scope(Optional<ScopeVO> scope) {
    this.value = scope;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param scope
   * @return
   */
  public T scope(String scope) {
    this.value = Optional.of(ScopeVO.from(scope));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T scopeNull() {
    this.value = Optional.empty();
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetScope() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetScopeIfMatches(final String field) {
    if ("scope".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
